{
  "status": "SUPPORTED",
  "task_summary": "Identify and assemble components at a marked spot on a workbench using a tool, then place the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "assembly_point",
        "entity_kind": "FIXED_TARGET",
        "function": "The marked location on the workbench where the fastening takes place.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["marked_area", "assembly_site"],
        "required_properties": ["fixed_on_workbench"]
      },
      {
        "id": "parts",
        "entity_kind": "OBJECT",
        "function": "The components that need to be fastened together or to the workbench.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["block", "piece", "component"],
        "required_properties": ["compatible_with_fastener"]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "The reusable equipment used to perform the fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "hammer", "gripper"],
        "required_properties": ["usable_for_fastening"]
      },
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "The material used to secure the parts.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screw", "clip", "adhesive"],
        "required_properties": ["connects_parts"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the tool is left after the task.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "surface"],
        "required_properties": ["flat", "wooden"]
      },
      {
        "id": "left_drawer",
        "entity_kind": "REGION",
        "function": "A storage area under the workbench that may contain tools.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["drawer", "storage"],
        "required_properties": ["closed", "under_desk"]
      },
      {
        "id": "right_drawer",
        "entity_kind": "REGION",
        "function": "A storage area under the workbench that may contain tools.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["drawer", "storage"],
        "required_properties": ["closed", "under_desk"]
      },
      {
        "id": "tall_cabinet",
        "entity_kind": "REGION",
        "function": "A storage unit against the wall that may contain tools.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["cabinet", "storage"],
        "required_properties": ["closed", "against_wall"]
      }
    ],
    "functional_relations": [
      {
        "id": "attached_to",
        "relation": "Parts must be attached to the assembly point.",
        "participant_roles": ["parts", "assembly_point"]
      ,
      "required": true
      },
      {
        "id": "joined_by",
        "relation": "Fastener joins the parts to the assembly point.",
        "participant_roles": ["parts", "fastener", "assembly_point"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "fastening",
        "operation": "Complete the fastening at the assembly point.",
        "participant_roles": ["assembly_point", "parts", "fastener", "tool"],
        "operation_count": 1
      },
      {
        "id": "placing_tool",
        "operation": "Leave the tool on the workbench.",
        "participant_roles": ["tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "assembly_point": [
        {"label": "tray_with_blocks", "visual_description": "A dark grey tray holding yellow and blue blocks on the table."}
      ],
      "parts": [
        {"label": "yellow_block", "visual_description": "A yellow rectangular block."},
        {"label": "blue_block", "visual_description": "A blue rectangular block."}
      ],
      "tool": [],
      "fastener": [],
      "workbench": [
        {"label": "wooden_table", "visual_description": "A wooden desk with drawers."}
      ],
      "left_drawer": [
        {"label": "closed_drawer", "visual_description": "A blue drawer with a handle, closed."}
      ],
      "right_drawer": [
        {"label": "closed_drawer", "visual_description": "A blue drawer with a handle, closed."}
      ],
      "tall_cabinet": [
        {"label": "closed_cabinet", "visual_description": "A tall blue cabinet with a door."}
      ]
    },
    "inspectable_regions": [
      {"id": "left_drawer", "label": "left_drawer", "visual_description": "Closed drawer under the table." , "reason": "Storage structure that may hide the tool or fastener."},
      {"id": "right_drawer", "label": "right_drawer", "visual_description": "Closed drawer under the table.", "reason": "Storage structure that may hide the tool or fastener."},
      {"id": "tall_cabinet", "label": "tall_cabinet", "visual_description": "Closed cabinet against the wall.", "reason": "Storage structure that may hide the tool or fastener."}
    ],
    "inspection_order": [
      "left_drawer",
      "right_drawer",
      "tall_cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
